export const productFeaturesTableHtml = '<table class="doc-feature-table">\n  <thead>\n    <tr>\n      <th class="doc-feature-table__head">类别</th>\n      <th class="doc-feature-table__head">特性</th>\n      <th class="doc-feature-table__head">描述</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="3">主页</td>\n      <td class="doc-feature-table__cell" rowspan="2">主页</td>\n      <td class="doc-feature-table__cell">提供多维度数据统计卡片</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">为不同用户提供各自视角的默认主页</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">资源总览</td>\n      <td class="doc-feature-table__cell">支持查看资源基本信息、容量信息、配置信息、硬件信息、相关对象等卡片</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">根节点</td>\n      <td class="doc-feature-table__cell" rowspan="1">根节点</td>\n      <td class="doc-feature-table__cell">支持管理根节点下的数据中心资源</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="6">数据中心</td>\n      <td class="doc-feature-table__cell" rowspan="2">数据中心生命周期管理</td>\n      <td class="doc-feature-table__cell">支持按需新建数据中心，并可在每个数据中心内建立独立的集群、数据存储、网络等资源</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持数据中心的新建、删除等基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">数据中心关联资源</td>\n      <td class="doc-feature-table__cell">支持集中查看和管理数据中心内的集群和主机、虚拟机、数据存储、镜像存储、存储目标、网络等资源</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">回收站</td>\n      <td class="doc-feature-table__cell">支持集中管理虚拟机、镜像、硬盘回收资源</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">导出清单</td>\n      <td class="doc-feature-table__cell">支持集中管理已导出的虚拟机和镜像资源，包括直接下载和复制下载链接</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">资源拓扑</td>\n      <td class="doc-feature-table__cell">以拓扑图形化展示数据中心资源规模数量</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="9">集群</td>\n      <td class="doc-feature-table__cell" rowspan="1">集群生命周期管理</td>\n      <td class="doc-feature-table__cell">支持集群的新建、修改配置、删除等基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">集群监控</td>\n      <td class="doc-feature-table__cell">支持查看集群内全部主机和虚拟机的可视化监控数据，包括 CPU、内存、硬盘、网卡</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">集群关联资源</td>\n      <td class="doc-feature-table__cell">支持集中查看和管理集群内的主机、虚拟机、数据存储、网络等资源</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="2">集群动态资源调度</td>\n      <td class="doc-feature-table__cell">支持监控集群内所有主机 CPU 或内存负载，并基于调度策略动态调整主机上运行的虚拟机业务</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持手动调度（用户根据调度建议手动执行资源调度）和自动调度（系统根据调度算法自动执行资源调度，用户无感知）两种策略</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">集群网络设置</td>\n      <td class="doc-feature-table__cell">支持对集群指定 VDI 网络和迁移网络</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">集群超配设置</td>\n      <td class="doc-feature-table__cell">支持设置集群 CPU 超配比和内存超配比，提高计算资源利用率</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">集群主机设置</td>\n      <td class="doc-feature-table__cell">支持以集群为粒度批量设置主机默认参数，包括设置主机 CPU 型号检测、ignore_msrs 参数、主机 Zero Copy、大页内存、主机预留内存</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">集群虚拟机设置</td>\n      <td class="doc-feature-table__cell">支持以集群为粒度批量设置虚拟机默认参数，包括虚拟机高可用、虚拟机跨集群高可用、指定虚拟机 CPU 模式、虚拟机 Hyper-V、虚拟机启动显卡类型、网卡多队列优化</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="18">主机</td>\n      <td class="doc-feature-table__cell" rowspan="1">主机生命周期管理</td>\n      <td class="doc-feature-table__cell">支持主机的添加、启停、重连、开关机、重启、进入/退出维护模式、修改配置、删除等基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">主机监控</td>\n      <td class="doc-feature-table__cell">支持对主机进行可视化监控，包括 CPU、内存、硬盘、网卡</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="7">主机关联资源</td>\n      <td class="doc-feature-table__cell">支持集中查看和管理主机上的虚拟机、Kernel 适配器资源</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">主机部署 SAN 存储后，支持集中查看主机上划分好的块设备；支持查看块设备路径</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持集中查看和管理主机上检测到的物理网卡和聚合口；支持查看网卡 LLDP 信息；支持聚合口状态检测，帮助用户及时定位故障网卡</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持集中管理主机上检测到的物理 GPU 设备；物理 GPU 设备可携带其上全部外设（包括：GPU 显卡、GPU 声卡、以及其它小设备）以组为单位整体透传给虚拟机使用，让虚拟机享有主机强劲的 GPU 并行计算能力</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持将主机上的物理 GPU 设备进行虚拟化切割；支持集中管理主机上切割后的 vGPU 设备；支持将 vGPU 设备透传给虚拟机使用</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持集中管理主机上检测到的 USB 设备；支持将 USB 设备透传给虚拟机使用</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持集中管理主机上检测到的其他 PCI 设备；支持设置 PCI 设备白名单；支持将 PCI 设备透传给虚拟机使用</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">主机 IPMI 纳管</td>\n      <td class="doc-feature-table__cell">用户填写正确的 IPMI 信息后，支持通过 IPMI 远程访问主机</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">主机电源控制</td>\n      <td class="doc-feature-table__cell">主机通过 IPMI 纳管后，支持获取和改变主机电源状态</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">主机 Web 终端</td>\n      <td class="doc-feature-table__cell">支持通过终端小窗直接访问主机系统，方便运维</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">主机修改 SSH 密码</td>\n      <td class="doc-feature-table__cell">支持更新主机 SSH 密码，修改后主机自动重连生效</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">密码加密存放</td>\n      <td class="doc-feature-table__cell">支持主机密码加密存放，保护用户数据隐私</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">Intel EPT 硬件辅助</td>\n      <td class="doc-feature-table__cell">支持针对 Intel CPU 开启 Intel EPT 硬件辅助功能，有效提升 CPU 性能</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">自定义标签</td>\n      <td class="doc-feature-table__cell">支持为主机标记标签，方便快速定位资源</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">自定义列表项</td>\n      <td class="doc-feature-table__cell">支持按需自定义展示特定信息列，实现个性化和高效信息呈现</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">导出 CSV 文件</td>\n      <td class="doc-feature-table__cell">支持将主机列表导出为 CSV 表格，方便统计分析与问题诊断</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="87">虚拟机</td>\n      <td class="doc-feature-table__cell" rowspan="1">虚拟机生命周期管理</td>\n      <td class="doc-feature-table__cell">支持虚拟机的新建、开关机、重启、恢复、暂停、强制关机、关闭电源、修改配置、导出等基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">虚拟机监控</td>\n      <td class="doc-feature-table__cell">支持对虚拟机进行可视化监控，包括CPU、内存、硬盘、网卡</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="2">自定义视图</td>\n      <td class="doc-feature-table__cell">支持主机视图，便捷查看虚拟机物理所属关系</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持分组视图，便捷管理同属性、同场景的虚拟机</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="6">虚拟机控制台</td>\n      <td class="doc-feature-table__cell">支持直接通过终端方式访问虚拟机</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持 VNC、SPICE、SPICE+VNC 三种控制台模式</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">VNC 控制台支持粘贴命令文本、支持虚拟机电源管理、支持控制台窗口大小自适应</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">SPICE 控制台支持设置屏幕数量</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持设置控制台密码；提供系统参数控制 VNC 控制台密码强度</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持实时预览虚拟机控制台画面，默认每 5 秒刷新一次</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="5">虚拟机 CPU</td>\n      <td class="doc-feature-table__cell">支持指定 CPU 总核数、每个插槽内核数</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持设置虚拟机 CPU 型号是否与主机 CPU 型号一致，从而继承主机部分或全部 CPU 特性，满足业务需求</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持指定 CPU 资源优先级，提高部分虚拟机在主机负载较高时的资源抢夺能力</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持将虚拟机的虚拟 CPU 与主机的物理 CPU 绑定，提高虚拟机性能</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持设置 EmulatorPin，将虚拟机中除 vCPU 和 I/O 线程外的其他线程与主机物理 CPU 绑定</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">虚拟机内存</td>\n      <td class="doc-feature-table__cell">支持指定内存资源优先级，提高部分虚拟机在主机负载较高时的资源抢夺能力</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="5">虚拟机硬盘</td>\n      <td class="doc-feature-table__cell">支持指定硬盘存储位置，满足虚拟机不同性能需求</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持选择 RDM 硬盘，虚拟机直接访问 LUN 设备</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持模拟不同硬盘总线类型</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持设置硬盘缓存模式，控制虚拟机数据写入硬盘时是否使用主机页面缓存</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持SAN 存储下多虚拟机共享使用同一硬盘</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="8">虚拟机网卡</td>\n      <td class="doc-feature-table__cell">支持虚拟机开机/关机状态下启用/停用网卡</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持虚拟机开机/关机状态下加载/卸载网卡</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持设置网卡型号，满足不同业务需求</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持设置网卡多队列数目，选择是否使用多个队列收发网络数据包，提升网络带宽性能</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持虚拟机开机/关机状态下设置网卡 QoS 限速</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持自定义指定虚拟机 IP 地址和 MAC 地址</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持自动通过 VMTools 下发和读取网络配置，如 IP 地址</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持设置网卡防欺诈模式，提供防 IP/MAC 伪造和 ARP 欺骗功能</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">虚拟机光驱</td>\n      <td class="doc-feature-table__cell">支持加载 ISO 镜像文件，通过 ISO 光驱启动虚拟机；支持单台虚拟机加载多个光驱，提升业务部署效率</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="5">虚拟机外接设备</td>\n      <td class="doc-feature-table__cell">支持虚拟机开机/关机状态下加载/卸载物理 GPU 设备/vGPU 设备</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持虚拟机开机/关机状态下加载/卸载 USB 设备</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持设置虚拟机显卡类型，包括 vga、virtio、qxl、cirrus</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持设置虚拟机声卡类型，包括 HDA(ICH6)、HDA(ICH9)、AC97</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持设置是否允许虚拟机热插拔 PCI 设备</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="3">虚拟机快照</td>\n      <td class="doc-feature-table__cell">支持对虚拟机进行临时状态保留，方便出现故障后迅速回滚</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">恢复快照支持整机恢复（同时恢复虚拟机数据和硬盘盘序）和自定义恢复（恢复指定硬盘）</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持恢复快照后自动将虚拟机开机</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="2">虚拟机克隆</td>\n      <td class="doc-feature-table__cell">克隆虚拟机整机数据，支持根据业务需求选择克隆方式，包括全量克隆、快速全量克隆</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持设置数据存储分配策略，包括自动分配、手动分配</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">虚拟机镜像</td>\n      <td class="doc-feature-table__cell">支持制作虚拟机镜像，方便定制化批量新建虚拟机</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="3">虚拟机模板</td>\n      <td class="doc-feature-table__cell">支持将虚拟机克隆为模板、转换为模板</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持模板转换为虚拟机、基于模板新建虚拟机</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持修改模板配置</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">虚拟机规范</td>\n      <td class="doc-feature-table__cell">支持自定义虚拟机规范，在批量部署场景中，可避免主机名或 SID 重复而冲突</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="4">虚拟机迁移-更改主机</td>\n      <td class="doc-feature-table__cell">将虚拟机迁移到其他主机，支持热迁移和冷迁移</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">热迁移：拷贝 CPU 相关寄存器状态及内存信息，支持本地存储、NFS 存储、SAN 存储</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">冷迁移：支持本地存储</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">若虚拟机长时间处于高业务状态而影响迁移，支持启用自动收敛模式，提升迁移成功率</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="3">虚拟机迁移-更改数据存储</td>\n      <td class="doc-feature-table__cell">将虚拟机迁移到其他数据存储</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持跨 SAN 存储热迁移和冷迁移</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持对带数据硬盘的虚拟机进行整机迁移（共享硬盘除外）</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="6">虚拟机迁移-更改主机和数据存储</td>\n      <td class="doc-feature-table__cell">将虚拟机迁移到其他主机和数据存储，支持热迁移和冷迁移</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持虚拟机跨同类型数据存储热迁移，包括：NFS 存储--NFS 数据存储、SAN 存储--SAN 存储</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持虚拟机跨不同类型数据存储热迁移，包括：本地存储--SAN 存储、本地存储--NFS 存储、SAN 存储--NFS 存储</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持虚拟机跨同类型数据存储冷迁移，包括：NFS 存储--NFS 存储</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">若虚拟机长时间处于高业务状态而影响迁移，支持启用自动收敛模式，提升迁移成功率</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">若已确保存储迁移后数据完整无损，支持手动清理迁移后保留的原始数据，释放存储空间</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">虚拟机 VMTools</td>\n      <td class="doc-feature-table__cell">支持虚拟机安装 VMTools工具与驱动，包括 QEMU Guest Agent (QGA)、Cloudbase-Init、agent 高级监控、Virtio 驱动</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="3">虚拟机高可用</td>\n      <td class="doc-feature-table__cell">主机故障时，支持虚拟机自动重启，UI 支持展示恢复进度</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持通过高可用策略全局控制虚拟机高可用功能</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持设置跨集群高可用策略</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="4">虚拟机安全</td>\n      <td class="doc-feature-table__cell">支持配置和管理标准密钥提供程序和内置密钥提供程序</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持密钥轮换，满足业务和合规性要求</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持添加虚拟可信平台模块（vTPM），为虚拟机操作系统提供增强的安全性</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持启用Secure Boot，提供高虚拟机抵御攻击的能力及基础设施可信程度</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">虚拟机注册</td>\n      <td class="doc-feature-table__cell">支持通过注册虚拟机配置文件和数据文件，在平台上创建一个对应的虚拟机记录。注册后，该虚拟机即可纳入平台统一管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">重置系统</td>\n      <td class="doc-feature-table__cell">支持恢复虚拟机到镜像初始状态，系统硬盘所有数据将被覆盖</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">更改虚拟机所有者</td>\n      <td class="doc-feature-table__cell">支持更改虚拟机所有者，修改后对应所有者拥有虚拟机全部权限</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">更改虚拟机分组</td>\n      <td class="doc-feature-table__cell">支持更改虚拟机所属分组，方便分类管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">自定义标签</td>\n      <td class="doc-feature-table__cell">支持为虚拟机标记标签，方便快速定位资源</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">设置主机名</td>\n      <td class="doc-feature-table__cell">支持虚拟机自定义主机名</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">虚拟机调度组</td>\n      <td class="doc-feature-table__cell">支持加入/退出虚拟机调度组，从而绑定/解绑对应的虚拟机调度策略，管控主机上的虚拟机分配情况</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">SSH 密钥注入</td>\n      <td class="doc-feature-table__cell">支持 Linux 虚拟机通过注入 SSH 公钥实现免密登录</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">User Data 导入</td>\n      <td class="doc-feature-table__cell">支持虚拟机导入 User Data，通过上传自定义的参数或脚本，对虚拟机进行定制化配置或完成特定任务</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">修改虚拟机密码</td>\n      <td class="doc-feature-table__cell">支持 Linux/Windows 虚拟机开机状态下修改虚拟机密码</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="3">虚拟机引导设置</td>\n      <td class="doc-feature-table__cell">支持设置虚拟机引导加载操作系统的优先顺序，支持硬盘、光盘、网络三种启动方式</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持设置 BIOS 模式，包括 Legacy、UEFI</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持设置 BIOS 界面的自动停留时间</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">隐藏 KVM 虚拟化标记</td>\n      <td class="doc-feature-table__cell">支持对单台虚拟机关闭CPU虚拟化标记，用于跳过部分软件对该虚拟机的虚拟化环境检测</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">VMware I/O 端口模拟</td>\n      <td class="doc-feature-table__cell">支持设置是否允许 KVM 虚拟机模拟 VMware 虚拟化环境中的 I/O 端口，实现与 VMware 虚拟化环境兼容</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">Hyper-V</td>\n      <td class="doc-feature-table__cell">支持是否开启虚拟机 Hyper-V 模拟功能（限 Windows 虚拟机）</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">导出 OVA 模板</td>\n      <td class="doc-feature-table__cell">支持导出虚拟机为 OVA 模板</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">自定义列表项</td>\n      <td class="doc-feature-table__cell">支持按需自定义展示特定信息列，实现个性化和高效信息呈现</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">导出 CSV 文件</td>\n      <td class="doc-feature-table__cell">支持将主机列表导出为 CSV 表格，方便统计分析与问题诊断</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="2">资源删除保护</td>\n      <td class="doc-feature-table__cell">提供虚拟机删除保护机制，用户确认后才能进行删除，降低误操作风险</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">提供虚拟机删除策略控制，包括立刻删除、延时删除（默认）、永不删除</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="21">裸金属管理</td>\n      <td class="doc-feature-table__cell" rowspan="3">裸金属模板</td>\n      <td class="doc-feature-table__cell">按生成机制划分，支持裸金属模板类型：系统模板、自定义模板</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持操作系统类型：平台定制版操作系统、主流 Linux 发行版操作系统（RHEL/CentOS 系列、Debian/Ubuntu 系列、SUSE/openSUSE 系列）</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持查看裸金属模板内容详情、下载裸金属模板</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="3">裸金属集群</td>\n      <td class="doc-feature-table__cell">支持裸金属集群的创建、删除等基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持裸金属集群加载、卸载部署服务器</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持裸金属集群加载、卸载分布式交换机</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">部署服务器</td>\n      <td class="doc-feature-table__cell">支持指定单独的服务器，为裸金属设备提供 PXE 服务和控制台代理服务</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="5">裸金属设备</td>\n      <td class="doc-feature-table__cell">按添加方式划分，支持手动添加和模板导入；最大允许一次性批量添加 500 台裸金属设备</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持裸金属设备的添加、启用、停用、开机、关机、重启、删除等基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持自动或手动方式获取裸金属设备的硬件信息</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持打开控制台，直接跳转至裸金属设备的 IPMI 管理界面</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持查看裸金属设备的硬件配置信息</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="9">裸金属主机</td>\n      <td class="doc-feature-table__cell">最大允许一次性批量创建 50 台裸金属主机</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持自定义选择镜像（ISO 格式且非 Live CD）安装裸金属主机操作系统</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持通过裸金属模板快速生成预配置文件，实现无人值守批量安装裸金属主机操作系统</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持为裸金属主机配置业务网络</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持裸金属主机的创建、启动、停止、重启、删除、还原、彻底删除等基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持打开裸金属主机控制台</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持自定义裸金属主机标签，方便快速查询定位资源</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持对裸金属主机进行可视化监控，包括：CPU、内存、磁盘读写、磁盘容量、网卡吞吐</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持查看裸金属主机的网卡和硬盘等关联资源</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="17">镜像存储</td>\n      <td class="doc-feature-table__cell" rowspan="9">单机镜像仓库</td>\n      <td class="doc-feature-table__cell">以镜像切片方式存放虚拟机和硬盘使用的镜像文件</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持单机镜像仓库的添加、启停、重连、修改配置、删除等基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持获取单机镜像仓库中挂载路径下的已有镜像文件</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持对单机镜像仓库指定数据网络，用于与主机之间进行数据通信</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">同一管理节点下不同单机镜像仓库间支持镜像同步，支持对单机镜像仓库指定镜像同步网络</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持清理镜像仓库中已被彻底删除的无效数据，释放存储空间</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持对单机镜像仓库更新密码</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持集中管理单机镜像仓库中的镜像资源</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持对单机镜像仓库已用容量百分比进行可视化监控</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="8">镜像管理</td>\n      <td class="doc-feature-table__cell">支持镜像的添加、修改配置、删除等基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持添加两种镜像类型，包括系统镜像、硬盘镜像</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持四种镜像格式，包括 qcow2、iso、vmdk、raw</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持两种镜像上传方式，包括 URL 上传、本地上传</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持 MD5 校验，确保上传的镜像完整无损</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持导出镜像</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持设置共享模式，包括全局共享、指定共享、不共享</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持资源删除保护，提供删除保护机制和删除策略控制</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="19">数据存储</td>\n      <td class="doc-feature-table__cell" rowspan="4">本地存储</td>\n      <td class="doc-feature-table__cell">支持图形化添加本地存储，支持使用主机空闲硬盘或本地目录作为数据存储</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持本地存储的添加、启停、重连、进入维护模式、删除等基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持集中管理本地存储关联的虚拟机、硬盘、主机、集群资源</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持可视化监控本地存储容量信息，包括存储使用率、存储分布、存储分配比</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="9">SAN 存储</td>\n      <td class="doc-feature-table__cell">采用共享块存储方式，支持通过 iSCSI 存储、FC 存储、NVMe 存储搭建</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持 SAN 存储的添加、启停、重连、进入维护模式、删除等基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持集中管理 SAN 存储关联的虚拟机、硬盘、集群、共享块资源</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持两种存储空间分配策略，包括厚置备、精简置备</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持指定存储网络，可使用此存储网络来判断虚拟机健康状态</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持添加多个共享块；若块设备扩容或更替，支持刷新查看存储容量变化</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持强制清理块设备中的数据，如文件系统、RAID或分区表中的标签等</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持清理跨 SAN 存储迁移后保留的原始数据</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持可视化监控 SAN 存储容量信息，包括存储使用率、存储分布、存储分配比</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="6">NFS 存储</td>\n      <td class="doc-feature-table__cell">采用网络文件系统的存储方式，支持自定义挂载参数</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持 NFS 存储的添加、启停、重连、进入维护模式、删除等基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持集中管理 NFS 存储关联的虚拟机、硬盘、集群资源</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持指定存储网络，可使用此存储网络来判断虚拟机健康状态</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持清理跨 NFS 存储迁移后保留的原始数据</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持可视化监控 NFS 存储容量信息，包括存储使用率、存储分布、存储分配比</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="17">网络资源</td>\n      <td class="doc-feature-table__cell" rowspan="7">分布式交换机</td>\n      <td class="doc-feature-table__cell">为集群内虚拟机提供统一虚拟网络管理和监控功能的虚拟交换机设备</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持自动生成默认分布式交换机，用于管理主机的管理网流量</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持基于默认分布式交换机新建分布式端口组，实现管理网&amp;业务网复用</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持分布式交换机的新建、删除等基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持 VLAN (802.1Q) 二层隔离</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持集中管理分布式交换机关联的主机的上行链路</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持集中管理分布式交换机下的分布式端口组、集群相关资源</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="8">分布式端口组</td>\n      <td class="doc-feature-table__cell">分布式交换机端口的逻辑分组，用于端口配置</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持分布式端口组的新建、修改配置、删除等基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持添加 IPv4/IPv6 类型网络</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持开启/关闭 IP 地址管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持开启/关闭 DHCP 服务</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持自定义 MTU，限制网络传输数据包的大小</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持集中管理分布式端口组的网络段、DNS 等资源</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持对分布式端口组的 IP 使用情况进行可视化监控及列表统计、有助于提高 IP 规划效率</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="2">Kernel 适配器</td>\n      <td class="doc-feature-table__cell">支持自动生成默认 Kernel 适配器，用于管理和配置物理网络</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持服务类型：管理、存储</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">网络服务</td>\n      <td class="doc-feature-table__cell" rowspan="1">安全组</td>\n      <td class="doc-feature-table__cell">为虚拟机网卡提供网络安全控制</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="7">网络拓扑</td>\n      <td class="doc-feature-table__cell" rowspan="7">/</td>\n      <td class="doc-feature-table__cell">支持以分布式交换机为中心展示完整链路关系等信息</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持刷新显示当前最新网络拓扑</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持将网络拓扑导出为 PNG 格式图片</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持隐藏或显示网络拓扑中的虚拟机</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持选中资源高亮显示、资源信息悬浮显示</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持适应画布、放大、缩小、全屏等画布操作</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持在当前拓扑范围内，按资源名称/UUID 检索资源</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="11">可靠服务</td>\n      <td class="doc-feature-table__cell" rowspan="2">管理节点监控</td>\n      <td class="doc-feature-table__cell">支持通过图形化界面搭建双管理节点环境，当其中任何一个管理节点失联，可秒级触发高可用切换，保障管理节点持续提供服务</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持查看管理节点信息，包括管理节点IP、节点状态、VIP和管理服务状态</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">动态资源调度策略</td>\n      <td class="doc-feature-table__cell">展示集群动态资源调度DRS列表，便捷查看平台DRS策略</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="4">虚拟机调度策略</td>\n      <td class="doc-feature-table__cell">支持四种调度策略，包括互斥虚拟机、聚集虚拟机、虚拟机互斥主机、虚拟机亲和主机</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持虚拟机调度策略的新建、启停、修改配置、删除等基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持根据业务要求划分一组虚拟机进行统一调度；支持虚拟机调度组的基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持根据业务要求划分一组主机进行统一调度；支持主机调度组的基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="4">高可用策略</td>\n      <td class="doc-feature-table__cell">支持通过高可用策略全局控制虚拟机高可用功能</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持基于管理网连接状态、存储网连接状态、以及业务网卡状态正常/故障组合表配置虚拟机故障迁移策略</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持修改主机故障判断策略、以及高可用相关高级设置</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持查看和筛选高可用迁移日志</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="11">数据保护</td>\n      <td class="doc-feature-table__cell" rowspan="4">快照管理</td>\n      <td class="doc-feature-table__cell">支持集中统一管理虚拟机/硬盘快照</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">快照管理界面一分为二，实现虚拟机与对应快照联动展示</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持按快照数量和快照容量对虚拟机列表排序展示</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持快照的创建、恢复、删除等基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="7">灾备管理</td>\n      <td class="doc-feature-table__cell">支持以树状文件夹形式查看已保护资源备份数据</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持两种数据恢复方式：覆盖恢复、备份新建</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持备份计划的新建、启用、停用、删除等基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持新建虚拟机备份计划和平台数据库备份计划</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持两种备份存储类型：本地备份存储、异地备份存储</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持三种备份存储添加方式：复用镜像存储、复用主机、专用备份存储</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持备份存储的添加、启用、停用、重连、删除等基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="24">监控报警</td>\n      <td class="doc-feature-table__cell" rowspan="1">资源监控</td>\n      <td class="doc-feature-table__cell">支持可视化展示资源性能监控图表，包括集群、主机、虚拟机、镜像存储、数据存储、分布式端口组</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="7">报警器</td>\n      <td class="doc-feature-table__cell">提供丰富的报警条目，满足针对多种资源类型、多种应用场景的监控报警需求</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">按应用场景划分，支持报警器类型：资源报警器、事件报警器</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">按生成机制划分，提供默认报警器，支持用户自定义报警器</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持报警器的新建、启停、删除等基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持三种报警级别：紧急、严重、提示</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">报警器支持按需开启报警恢复通知，开启后，报警器内的任一资源从报警状态恢复至正常状态，系统将接收到一次恢复通知</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持集中管理报警器的相关通知对象、以及报警记录</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="2">消息模板</td>\n      <td class="doc-feature-table__cell">将报警消息推送至各通知对象时，支持自定义报警消息模板</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持消息模板的创建、修改配置、删除等基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="5">通知对象</td>\n      <td class="doc-feature-table__cell">提供系统默认通知对象，支持系统通知对象的启用、停用等基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持自定义通知对象，包括邮箱、钉钉、飞书、企业微信、HTTP 应用、Microsoft Teams</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持自定义通知对象的创建、启用、停用、删除等基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持通知对象添加、移除报警器；支持集中管理通知对象的相关报警器</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持集中管理通知对象的接收的相关报警消息</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="9">报警消息</td>\n      <td class="doc-feature-table__cell">支持直观查看和统一管理平台报警消息，提高运维效率</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持以柱状图方式直观查看近一周不同报警级别的报警消息</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持以饼图方式直观查看近一周不同资源的报警消息</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持以列表方式查看最多高达 1000 条报警消息</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持多种筛选规则，包括资源类型、时间段、报警级别、消息类型、已读未读状态</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持对报警消息设置沉默周期，在沉默周期内报警器将不再发出报警，用户可灵活选择合适时间再处理报警信息</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持对报警消息恢复报警，取消沉默周期</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持查看报警消息详情</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持报警消息列表导出为CSV表格，便于统计分析及问题诊断；支持导出筛选后的报警消息数据</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="14">任务事件</td>\n      <td class="doc-feature-table__cell" rowspan="4">操作任务</td>\n      <td class="doc-feature-table__cell">显示平台的历史操作任务，针对已完成的历史操作提供日志查看</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持多种筛选规则，包括时间段、任务结果、操作员</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持查看平台操作任务详情</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持以 CSV 格式导出平台操作任务日志</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="4">高可用任务</td>\n      <td class="doc-feature-table__cell">支持集中查看和管理已触发的高可用迁移任务</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持多种筛选规则，包括时间段、任务结果</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持查看高可用任务详情</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持以 CSV 格式导出高可用任务日志</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="3">调度任务</td>\n      <td class="doc-feature-table__cell">支持集中查看和管理调度执行历史、执行结果、执行时间等信息</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持查看调度任务详情</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持以 CSV 格式导出调度任务日志</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="3">事件</td>\n      <td class="doc-feature-table__cell">支持监控并记录平台所有活动事件，有效保障环境安全</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持多种筛选规则，包括时间段、任务结果</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持查看事件详情</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="2">日志收集</td>\n      <td class="doc-feature-table__cell" rowspan="1">日志收集</td>\n      <td class="doc-feature-table__cell">支持收集平台以及各类节点在指定时间段内产生的日志</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">日志管理</td>\n      <td class="doc-feature-table__cell">支持日志收集、取消收集、下载、以及删除操作</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="5">标签管理</td>\n      <td class="doc-feature-table__cell" rowspan="5">/</td>\n      <td class="doc-feature-table__cell">支持对资源定制化创建标签，可通过标签类型及标签名称快速过滤出所需资源</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持标签类型：管理员标签、用户标签</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持标签的创建、删除等基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">管理员标签支持绑定、解绑所有资源，用户标签支持绑定、解绑相应用户资源</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持集中管理标签绑定的相关资源</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="4">自定义属性</td>\n      <td class="doc-feature-table__cell" rowspan="4">/</td>\n      <td class="doc-feature-table__cell">支持创建自定义属性，通过属性键和属性值可快速筛选目标资源</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持为以下资源创建自定义属性：全局、主机、虚拟机、数据存储、分布式交换机、分布式端口组、裸金属主机</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持自定义属性的创建、删除等基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持集中查看属性值绑定的关联资源</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="4">迁移服务</td>\n      <td class="doc-feature-table__cell" rowspan="1">迁移服务</td>\n      <td class="doc-feature-table__cell">支持将其他虚拟化平台中的虚拟机系统及数据完整迁移至当前平台。支持的源平台包括 VMware vSphere 和其他基于 KVM 的云平台。通过分步向导指引，完成端到端的迁移流程</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="2">迁移资源</td>\n      <td class="doc-feature-table__cell">支持源平台的添加、删除等基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持数据网关的添加、删除等基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">迁移任务</td>\n      <td class="doc-feature-table__cell">支持迁移任务的创建、修改配置、同步、测试、删除等基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="33">系统管理</td>\n      <td class="doc-feature-table__cell" rowspan="6">用户管理</td>\n      <td class="doc-feature-table__cell">用户由admin创建或统一认证系统同步，且受admin管理，用户对自己创建的虚拟资源拥有管理权限</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持本地用户的创建、删除等基本生命周期管理；支持统一认证用户的同步、删除等基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持对用户进行双因子登录认证；支持查看用户的双因子二维码；支持下载用户的双因子二维码</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持设置和集中管理用户配额，包括：计算资源、存储资源、网络资源、其它</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持集中管理用户的关联资源、共享资源</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持普通用户变更为管理员用户</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="3">用户组管理</td>\n      <td class="doc-feature-table__cell">用户组是一组用户的集合，支持以用户组为单位进行权限控制。</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持用户组的新建、删除等基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持集中管理用户组内的用户、用户组绑定的角色、共享给用户组的资源</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="4">角色管理</td>\n      <td class="doc-feature-table__cell">角色是一组权限的集合，为用户和用户组授予权限可获得调用相关 API 进行资源操作的能力。</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">按生成机制划分，支持系统角色和自定义角色</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持自定义角色的新建、克隆、修改、删除等基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">自定义角色支持修改界面权限和 API 相关权限</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="3">统一认证 SSO</td>\n      <td class="doc-feature-table__cell">支持通过添加统一认证服务器，无缝接入统一登录认证系统，使相应用户免密登录平台</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持添加统一认证服务器类型：OIDC 服务器、AD 服务器、LDAP 服务器</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持统一认证服务器的添加、删除等基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="2">控制台代理</td>\n      <td class="doc-feature-table__cell">支持设置控制台代理地址，通过代理地址登录虚拟机控制台</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持重连控制台代理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="6">SNMP 管理</td>\n      <td class="doc-feature-table__cell">支持第三方平台通过 SNMP 协议监控平台资源数据，并接收平台推送的报警消息</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持启用/停用 SNMP 管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持可视化配置 SNMP 参数</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持添加 SNMP Trap 接收端，用于接收平台报警消息</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持 SNMP Trap 接收端的添加、编辑、删除等基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持将 SNMP Trap 接收端添加为通知对象并绑定到指定报警器</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="2">AccessKey 管理</td>\n      <td class="doc-feature-table__cell">提供访问平台 API 的身份凭证</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持 AccessKey 的生成、启用、停用、删除等基本生命周期管理</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">安全设置</td>\n      <td class="doc-feature-table__cell">支持集中统一管理平台登录策略、虚拟机安全策略、主机安全策略、保障安全</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">证书管理</td>\n      <td class="doc-feature-table__cell">支持配置和管理SSL证书，包括第三方证书和系统自签证书</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">日志服务器</td>\n      <td class="doc-feature-table__cell">支持收集管理节点日志，快速定位问题，提高运维效率</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">邮箱服务器</td>\n      <td class="doc-feature-table__cell">若报警通知对象为邮箱，需设置邮箱服务器，用来发送报警邮件</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="3">系统参数</td>\n      <td class="doc-feature-table__cell">提供平台层面的功能特性设置，一经设置，平台全局范围内生效</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持一键恢复至初始默认值</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell">支持快速搜索以及目录导航，帮助用户快速定位目标条目</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="5">UI 特色功能</td>\n      <td class="doc-feature-table__cell" rowspan="1">快速导航入口</td>\n      <td class="doc-feature-table__cell">提供快速导航入口，方便用户快速定位并进入所需功能与服务</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">全局搜索</td>\n      <td class="doc-feature-table__cell">提供一站式全局搜索，搜索对象分类两大类：功能入口、资源</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">资源树右键操作</td>\n      <td class="doc-feature-table__cell">支持资源树展开时右键呼出操作面板</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">键盘快捷键</td>\n      <td class="doc-feature-table__cell">提供全局快捷键和页面快捷键，支持键盘组合键快速访问菜单，提升用户体验与操作效率</td>\n    </tr>\n    <tr>\n      <td class="doc-feature-table__cell" rowspan="1">国际化</td>\n      <td class="doc-feature-table__cell">支持切换 UI 界面语言，包括简体中文和英文</td>\n    </tr>\n  </tbody>\n</table>\n';
